"""Environment diagnostic checks."""

from .models import CheckResult, CheckStatus


def run_checks(verbose: bool = False) -> list[CheckResult]:
    """Run environment diagnostic checks."""
    results = []
    results.append(_check_registry_parseable())
    results.append(_check_orphaned_kernels())
    if verbose:
        results.extend(_check_all_environments())
    return results


def _check_registry_parseable() -> CheckResult:
    """Check if the environment registry is parseable."""
    import json
    from pathlib import Path

    registry_path = Path.home() / ".qbraid" / "environments.json"

    if not registry_path.exists():
        return CheckResult(
            name="environments.registry",
            category="environments",
            status=CheckStatus.PASS,
            message="No environment registry file (none registered yet).",
        )

    try:
        data = json.loads(registry_path.read_text())
        count = len(data) if isinstance(data, (list, dict)) else 0
        return CheckResult(
            name="environments.registry",
            category="environments",
            status=CheckStatus.PASS,
            message=f"Environment registry is valid. {count} entries.",
        )
    except json.JSONDecodeError as exc:
        return CheckResult(
            name="environments.registry",
            category="environments",
            status=CheckStatus.FAIL,
            message=f"Environment registry is corrupted: {exc}",
            fix_hint=f"Back up and recreate: cp {registry_path} {registry_path}.bak",
        )
    except Exception as exc:
        return CheckResult(
            name="environments.registry",
            category="environments",
            status=CheckStatus.ERROR,
            message=f"Could not read environment registry: {exc}",
        )


def _check_orphaned_kernels() -> CheckResult:
    """Check for Jupyter kernels with missing Python executables."""
    try:
        from qbraid_core.services.environments.kernels import find_orphaned_kernels

        orphaned = find_orphaned_kernels()

        if not orphaned:
            return CheckResult(
                name="environments.orphaned_kernels",
                category="environments",
                status=CheckStatus.PASS,
                message="No orphaned Jupyter kernels found.",
            )

        names = [k.get("name", "?") for k in orphaned[:5]]
        return CheckResult(
            name="environments.orphaned_kernels",
            category="environments",
            status=CheckStatus.WARN,
            message=f"{len(orphaned)} orphaned kernel(s) found: {names}",
            fix_hint="Clean up with: qbraid kernels clean",
            details={"count": len(orphaned), "names": names},
        )
    except ImportError:
        return CheckResult(
            name="environments.orphaned_kernels",
            category="environments",
            status=CheckStatus.SKIP,
            message="Environment management not available (missing dependencies).",
        )
    except Exception as exc:
        return CheckResult(
            name="environments.orphaned_kernels",
            category="environments",
            status=CheckStatus.ERROR,
            message=f"Could not check for orphaned kernels: {exc}",
        )


def _check_all_environments() -> list[CheckResult]:
    """Check health of all registered environments (verbose mode only)."""
    results: list[CheckResult] = []

    try:
        import json
        from pathlib import Path

        from qbraid_core.services.environments.venv import is_venv_healthy

        registry_path = Path.home() / ".qbraid" / "environments.json"
        if not registry_path.exists():
            return results

        data = json.loads(registry_path.read_text())
        envs = (
            data
            if isinstance(data, list)
            else list(data.values()) if isinstance(data, dict) else []
        )

        for env in envs[:20]:  # Cap at 20 to avoid long runs
            slug = env.get("slug", env.get("name", "unknown"))
            venv_path = env.get("path") or env.get("venvPath")

            if not venv_path:
                continue

            path = Path(venv_path)
            if not path.exists():
                results.append(
                    CheckResult(
                        name=f"environments.health.{slug}",
                        category="environments",
                        status=CheckStatus.FAIL,
                        message=f"Environment '{slug}' path does not exist: {venv_path}",
                    )
                )
                continue

            try:
                health = is_venv_healthy(path)
                if health.is_healthy:
                    results.append(
                        CheckResult(
                            name=f"environments.health.{slug}",
                            category="environments",
                            status=CheckStatus.PASS,
                            message=f"Environment '{slug}' is healthy.",
                        )
                    )
                else:
                    issues = [str(i) for i in health.issues[:3]]
                    results.append(
                        CheckResult(
                            name=f"environments.health.{slug}",
                            category="environments",
                            status=(
                                CheckStatus.WARN if health.repairable_issues else CheckStatus.FAIL
                            ),
                            message=f"Environment '{slug}' has issues: {issues}",
                            fix_hint=(
                                "Run 'qbraid envs repair' to fix"
                                if health.repairable_issues
                                else None
                            ),
                        )
                    )
            except Exception as exc:
                results.append(
                    CheckResult(
                        name=f"environments.health.{slug}",
                        category="environments",
                        status=CheckStatus.ERROR,
                        message=f"Could not check '{slug}': {exc}",
                    )
                )
    except Exception:
        pass

    return results
